    private function do_fetch_events($params = array()) {
        /**
         * fetches prediction-market events (market topics); the call must be scoped by query/queries/tags, eventId, or an l1Category/l2Category listing filter
         *
         * @see https://dev.predict.fun/get-categories-25326910e0
         * @see https://dev.predict.fun/search-categories-and-markets-27399810e0
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->query] a single search term — routes the call through GET /v1/search instead of the categories listing
         * @param {string[]} [$params->queries] multiple search terms (alternative to query), searched one by one and merged deduplicated by event $slug
         * @param {string[]} [$params->tags] predictfun tag ids
         * @param {string} [$params->slug] direct lookup by event $slug
         * @param {int} [$params->limit] the maximum number of events to return, capped at 25 per search term when searching
         * @param {string} [$params->sort] 'VOLUME_24H_DESC' | 'VOLUME_ALL_DESC' | 'PUBLISHED_AT_ASC' | 'PUBLISHED_AT_DESC'
         * @param {string} [$params->status] 'OPEN' | 'RESOLVED'
         * @param {string} [$params->marketVariant] predictfun enum value ('SPORTS_MATCH', 'CRYPTO_UP_DOWN' etc.)
         * @return {array[]} a list of [prediction event structures](https://docs.ccxt.com/#/?id=prediction-event-structure)
         */
        $allowUnscopedFetchEvents = $this->safe_bool($this->options, 'allowUnscopedFetchEvents', false);
        if (!$allowUnscopedFetchEvents) {
            $this->require_event_query($params);
        }
        $queries = $this->parse_search_queries($params);
        $queriesLength = count($queries);
        $paramsValue = $this->omit($params, array( 'query', 'queries' ));
        // keys dropped before the client-side pass; the categories listing also drops its limit
        $postOmitKeys = array( 'tags' );
        $userLimit = $this->safe_integer($paramsValue, 'limit');
        $fetchCap = $this->safe_integer($this->options, 'maxFetchEventsResults', 100);
        if ($userLimit !== null) {
            $fetchCap = $userLimit;
        }
        $slug = $this->safe_string_2($paramsValue, 'slug', 'eventId');
        $rest = $this->omit($paramsValue, array( 'status', 'limit', 'sort', 'eventId', 'slug', 'tags', 'marketVariant' ));
        if ($this->markets === null) {
            $this->markets = $this->create_safe_dictionary();
        }
        $rawTopics = array();
        if ($slug !== null) {
            $response = Async\await($this->predictfunGetV1CategoriesSlug($this->extend(array( 'slug' => $slug ), $rest)));
            $data = $this->safe_dict($response, 'data');
            $rawTopics = array( $data );
        } elseif ($queriesLength > 0) {
            // a query/queries scope is answered by the dedicated search endpoint — the categories
            // listing has no text filter, so paging it and matching client-side would both miss
            // the venue's semantic matches and cost one request per page
            $rawTopics = Async\await($this->fetch_raw_topics_by_queries($queries, $paramsValue));
        } else {
            $request = array();
            $tags = $this->safe_list($paramsValue, 'tags', array());
            $tagsLength = count($tags);
            if ($tagsLength > 0) {
                $tagsString = implode(',', $tags);
                $request['tagIds'] = $tagsString;
            }
            $postOmitKeys[] = 'limit';
            $paramsCategories = $this->omit($paramsValue, array( 'limit', 'tags' ));
            $extendedRequest = $this->extend($request, $paramsCategories);
