            //                         "level": 2,
            //                         "makerRebateBps": 0,
            //                         "name": "15 Min",
            //                         "parentId": "2"
            //                     }
            //                 ],
            //                 "teams": null,
            //                 "title": "Ethereum Up or Down - August 27, 10AM-10:15AM ET",
            //                 "variantData": {
            //                     "endPrice": null,
            //                     "priceFeedId": "0x0003543336278a459ac24c2f239ffa36f279cadc71f4babc9f8126c6ff10011d",
            //                     "priceFeedProvider": "CHAINLINK",
            //                     "priceFeedSymbol": "ETHUSDT",
            //                     "startPrice": null,
            //                     "type": "CRYPTO_UP_DOWN"
            //                 },
            //                 "variantDetails": {
            //                     "crypto": {
            //                         "priceFeedId": "0x0003543336278a459ac24c2f239ffa36f279cadc71f4babc9f8126c6ff10011d",
            //                         "priceFeedProvider": "CHAINLINK",
            //                         "priceFeedSymbol": "ETHUSDT"
            //                     },
            //                     "upDown": {
            //                         "priceFeedId": "0x0003543336278a459ac24c2f239ffa36f279cadc71f4babc9f8126c6ff10011d",
            //                         "priceFeedProvider": "CHAINLINK",
            //                         "priceFeedSymbol": "ETHUSDT"
            //                     }
            //                 }
            //             }
            //         ],
            //         "success": true
            //     }
            //
            $data = $this->safe_list($rawTopicsResponse, 'data', array());
            $rawTopics = $this->array_concat($rawTopics, $data);
            $topicsLength = count($rawTopics);
            while ($topicsLength < $fetchCap) {
                $nextPageToken = $this->safe_string($rawTopicsResponse, 'cursor');
                if ($nextPageToken === null) {
                    break;
                }
                $extendedRequest['after'] = $nextPageToken;
                $rawTopicsResponse = Async\await($this->predictfunGetV1Categories($extendedRequest));
                $data = $this->safe_list($rawTopicsResponse, 'data', array());
                $rawTopics = $this->array_concat($rawTopics, $data);
                $topicsLength = count($rawTopics);
            }
            if ($topicsLength > $fetchCap) {
                $rawTopics = $this->array_slice($rawTopics, 0, $fetchCap);
            }
        }
        $rawTopicsLength = count($rawTopics);
        $result = array();
        for ($i = 0; $i < $rawTopicsLength; $i++) {
            $parsedEvent = $this->parse_event($rawTopics[$i]);
            $result[] = $parsedEvent;
            $parsedMarkets = $this->safe_list($parsedEvent, 'markets', array());
            $parsedMarketsLength = count($parsedMarkets);
            for ($mi = 0; $mi < $parsedMarketsLength; $mi++) {
                $m = $parsedMarkets[$mi];
                // prediction market rows are keyed by the unified 'market' handle
                $handle = $this->safe_string($m, 'market');
                if ($handle !== null) {
                    $this->markets[$handle] = $m;
                }
            }
        }
        $this->populate_outcomes();
        // scoping already happened server-side: the tag filter needs an event-level tags field
        // predictfun topics lack, and the query filter would drop semantic-search matches whose
        // title uses different words than the query
        $postParams = $this->omit($paramsValue, $postOmitKeys);
        // status is documented as the venue enum ('OPEN' / 'RESOLVED') but the shared client-side
        // pass speaks the unified vocabulary — translate so it doesn't discard every row it matched
        $rawStatus = $this->safe_string($paramsValue, 'status');
        if ($rawStatus === 'OPEN') {
            $postParams = $this->extend($postParams, array( 'status' => 'active' ));
        } elseif ($rawStatus === 'RESOLVED') {
            $postParams = $this->extend($postParams, array( 'status' => 'closed' ));
        }
        return $this->apply_event_fetch_params($result, $postParams, $queries);
    }

    public function fetch_raw_topics_by_queries(array $queries, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_raw_topics_by_queries(...))($queries, $params);
    }

    private function do_fetch_raw_topics_by_queries(array $queries, $params = array()) {
        /**
         * @ignore
         * searches $categories and $markets for every query term and returns the raw market topics, deduplicated by slug
         *
         * @see https://dev.predict.fun/search-$categories-and-$markets-27399810e0
         *
         * @param {string[]} $queries the search terms
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->status] anything other than 'active' asks the venue to include resolved rows
         * @return {array[]} an array of raw market topics, each with a nested $markets list
         */
        // always ask for the venue's maximum page size - this is the per-type page size of the
        // search endpoint (it caps at 25 and defaults to 10), not the caller's event limit, which
        // applyEventFetchParams () applies to the parsed events afterwards
        $limit = 25;
        // resolved rows are excluded unless asked for — the unified status filter drives that
        $status = $this->safe_string($params, 'status');
        $includeResolved = 'false';
        if (($status !== null) && ($status !== 'active') && ($status !== 'OPEN')) {
            $includeResolved = 'true';
        }
        // marketVariant/tags/sort are categories-listing filters the search endpoint does not accept
        $rest = $this->omit($params, array( 'query', 'queries', 'limit', 'sort', 'searchIn', 'status', 'eventId', 'slug', 'tags', 'marketVariant' ));
        $queriesLength = count($queries);
        $result = array();
        // the venue answers every term separately and the same category comes back for each term
        // that matches it - emit it once, otherwise applyEventFetchParams (), which slices to the
        // caller's limit after filtering, spends a slot on a repeat instead of a distinct event
        $seenSlugs = array();
        // market rows whose category row did not come back, bucketed by the slug they carry
        $orphanMarkets = array();
        $orphanSlugs = array();
        for ($i = 0; $i < $queriesLength; $i++) {
            $request = array(
                'query' => $queries[$i],
                'limit' => $limit,
                'includeResolved' => $includeResolved,
            );
            $response = Async\await($this->predictfunGetV1Search($this->extend($request, $rest)));
            //
            //     {
            //         "data": {
            //             "categories": [
            //                 {
            //                     "id": 405022,
            //                     "slug": "eth-updown-15m-1787839200",
            //                     "title": "Ethereum Up or Down - August 27, 10AM-10:15AM ET",
            //                     "description": "This market will resolve to \"Up\" ...",
            //                     "imageUrl": "https://static.predict.fun/automarket-eth-usd-15-minutes",
            //                     "isNegRisk": false,
            //                     "isYieldBearing": false,
            //                     "marketVariant": "CRYPTO_UP_DOWN",
            //                     "variantData": null,
            //                     "createdAt": "2026-08-26T14:00:02.000Z",
            //                     "publishedAt": "2026-08-26T14:00:20.780Z",
            //                     "startsAt": "2026-08-27T14:00:00.000Z",
            //                     "endsAt": "2026-08-27T14:15:00.000Z",
            //                     "status": "OPEN",
            //                     "isVisible": true,
            //                     "tags": [ { "id": "2", "name": "Crypto" } ],
            //                     "markets": [ { "id": 1739803, "categorySlug": "eth-updown-15m-1787839200", ... } ]
            //                 }
            //             ],
            //             "markets": [
            //                 {
            //                     "id": 1739803,
            //                     "imageUrl": "https://static.predict.fun/automarket-eth-usd-15-minutes",
            //                     "title": "Ethereum Up or Down - August 27, 10AM-10:15AM ET",
            //                     "question": "Ethereum Up or Down - August 27, 10AM-10:15AM ET",
            //                     "description": "This market will resolve to \"Up\" ...",
            //                     "tradingStatus": "OPEN",
            //                     "status": "REGISTERED",
            //                     "isVisible": true,
            //                     "isNegRisk": false,
            //                     "isYieldBearing": false,
            //                     "feeRateBps": 200,
            //                     "conditionId": "0xa8e9c348c299989329debd86aaef81a1c4880d42c3954a684bdc731f7a113487",
            //                     "outcomes": [ { "name": "Up", "indexSet": 1, "onChainId": "630152...", "status": null } ],
            //                     "isBoosted": false,
            //                     "categorySlug": "eth-updown-15m-1787839200",
            //                     "marketVariant": "CRYPTO_UP_DOWN"
            //                 }
            //             ]
            //         },
            //         "success": true
            //     }
            //
            $data = $this->safe_dict($response, 'data', array());
            $categories = $this->safe_list($data, 'categories', array());
            $categoriesLength = count($categories);
            for ($ci = 0; $ci < $categoriesLength; $ci++) {
                $category = $this->safe_dict($categories, $ci);
                $categorySlug = $this->safe_string($category, 'slug');
                if ($categorySlug === null) {
                    // nothing to key a duplicate on, keep the row rather than drop it
                    $result[] = $category;
                } elseif (!(is_array($seenSlugs) && array_key_exists($categorySlug ?? '', $seenSlugs))) {
                    $seenSlugs[$categorySlug] = true;
                    $result[] = $category;
                }
            }
            // a term can match a market whose category row is not in the response - those rows are
            // the other half of the payload and would otherwise be dropped, so bucket them by the
            // categorySlug they carry
            $rawMarkets = $this->safe_list($data, 'markets', array());
            $rawMarketsLength = count($rawMarkets);
            for ($mi = 0; $mi < $rawMarketsLength; $mi++) {
                $rawMarket = $rawMarkets[$mi];
                $marketSlug = $this->safe_string($rawMarket, 'categorySlug');
                if ($marketSlug !== null) {
                    if (is_array($orphanMarkets) && array_key_exists($marketSlug ?? '', $orphanMarkets)) {
                        // push through a local and write the slice back - the go transpiler's
                        // AppendToArray reassigns only a local copy of a map-stored array
                        $bucket = $orphanMarkets[$marketSlug];
                        $bucket[] = $rawMarket;
                        $orphanMarkets[$marketSlug] = $bucket;
                    } else {
                        $orphanMarkets[$marketSlug] = array( $rawMarket );
                        $orphanSlugs[] = $marketSlug;
                    }
                }
            }
        }
        // whatever the category rows did not claim is a market-only hit: synthesize the enclosing
        // topic from the market rows themselves, without spending a request per slug
        $orphanSlugsLength = count($orphanSlugs);
        for ($i = 0; $i < $orphanSlugsLength; $i++) {
            $orphanSlug = $orphanSlugs[$i];
            if (!(is_array($seenSlugs) && array_key_exists($orphanSlug ?? '', $seenSlugs))) {
                $seenSlugs[$orphanSlug] = true;
                $markets = $orphanMarkets[$orphanSlug];
                $first = $this->safe_dict($markets, 0, array());
                // the market row's 'status' is the registration enum ('REGISTERED' /
                // 'DEREGISTERED'), while parseEvent () reads the topic vocabulary ('OPEN' /
                // 'RESOLVED') - copying it verbatim would report resolved: false for a resolved hit
                $marketStatus = $this->safe_string($first, 'status');
                $tradingStatus = $this->safe_string($first, 'tradingStatus');
                $topicStatus = null;
                if (($marketStatus === 'RESOLVED') || ($marketStatus === 'SETTLED')) {
                    $topicStatus = 'RESOLVED';
                } elseif ($tradingStatus === 'OPEN') {
                    $topicStatus = 'OPEN';
                }
                $result[] = array(
                    // these rows carry no topic id and no endsAt, so the slug stands in as the id:
                    // it is what the venue addresses the topic by, and it keeps the event out of
                    // the caches and filters that key on an id being present.
                    // the missing endsAt is a known and accepted limit of synthesizing without a
                    // request: a market-only hit has no 'end', so its markets have no expiry and
                    // applyEventFetchParams () has nothing to filter or sort them on. recovering
                    // it would cost one GET /v1/categories/{slug} per orphan slug
                    'id' => $orphanSlug,
                    'slug' => $orphanSlug,
                    'title' => $this->safe_string($first, 'title'),
                    'description' => $this->safe_string($first, 'description'),
                    'imageUrl' => $this->safe_string($first, 'imageUrl'),
                    'marketVariant' => $this->safe_string($first, 'marketVariant'),
                    'isNegRisk' => $this->safe_bool($first, 'isNegRisk'),
                    'isYieldBearing' => $this->safe_bool($first, 'isYieldBearing'),
                    'isVisible' => $this->safe_bool($first, 'isVisible'),
                    'status' => $topicStatus,
                    'createdAt' => $this->safe_string($first, 'createdAt'),
                    'markets' => $markets,
                );
            }
        }
        return $result;
    }

